/* app do cliente: marca como recebida cada resposta do contador que chegou aqui (o contador vê o recebimento) */
function pedRecebe(){var m=0;MULTI.emps.forEach(function(e){var d=MULTI.data[e.id];(d&&d.ped||[]).forEach(function(p){if((p.rsn||0)>(p.rcb||0)){p.rcb=p.rsn;p.rcbH=horaAgora();m=1;}});});return m;}
function esc(s){return String(s==null?'':s).replace(/[&<>"]/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
function hoje(){var d=NOW(),m=['jan','fev','mar','abr','mai','jun','jul','ago','set','out','nov','dez'];return ('0'+d.getDate()).slice(-2)+' '+m[d.getMonth()];}
function money(v){var n=parseFloat(String(v||'').replace(/\./g,'').replace(',','.'));return isNaN(n)?0:n;}
function fmt(n){return n.toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2});}

