 arqList().forEach(function(a){if(a.or!=='ct'||a.st!=='disp'||(a.ped&&voce[a.ped]))return;if(/contrato|rescis|aviso de f[ée]rias|aviso pr[ée]vio/i.test(a.n))r.push({k:'arq:'+a.id,t:'Assinar '+a.n,go:'arq-'+a.id});});
