var VARS=[{k:'adi',l:'Adiantamento',u:'R$',sg:-1},{k:'ajuda',l:'Ajuda de custo',u:'R$',sg:1},{k:'atraso',l:'Atrasos',u:'h'},{k:'bonus',l:'Bônus',u:'R$',sg:1},{k:'com',l:'Comissões',u:'R$',sg:1},
 {k:'desc',l:'Desconto',t:'desc'},{k:'falta',l:'Faltas',t:'falta'},{k:'gorj',l:'Gorjeta',u:'R$',sg:1},{k:'grat',l:'Gratificações',u:'R$',sg:1},{k:'hen',l:'Hora extra noturna',t:'he'},
 {k:'he',l:'Horas extras',t:'he'},{k:'not',l:'Horas noturnas',u:'h'},{k:'hor',l:'Horas trabalhadas (horista)',u:'h'},{k:'insal',l:'Insalubridade',t:'insal'},{k:'peric',l:'Periculosidade',t:'peric'}];
