function normVars(vs){vs=vs||{};if(vs.he50||vs.he100){vs.he={p:vs.he100?'100':'50',h:vs.he100||vs.he50};delete vs.he50;delete vs.he100;}
 if(typeof vs.falta==='string')vs.falta={m:'dias',d:vs.falta,h:''};if(typeof vs.desc==='string')vs.desc={v:vs.desc,d:''};return vs;}
function vHas(k,x){if(!x)return false;if(typeof x==='string')return !!x;if(k==='he'||k==='hen')return !!x.h;if(k==='insal')return !!x.g;if(k==='peric')return true;if(k==='falta')return !!(x.d||x.h);if(k==='desc')return !!x.v;return false;}
var MESES_ANO=['Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'].map(function(m){return m+'/2026';});
var FST={rascunho:['Rascunho','neutral'],finalizada:['Finalizada · não enviada','warn'],enviada:['Enviada ao contador','info'],fechada:['Folha fechada','ok']};
var COMPS=['Outubro/2026','Novembro/2026','Setembro/2026'];
/*seed*/if(typeof ST0!=="undefined"&&!ST0.folhas)ST0.folhas=[{id:'fl1',comp:'Setembro/2026',func:'Ana Lima',tipo:'Mensal',st:'fechada',vars:{he50:'6',com:'350,00'},obs:'',data:'25 set'}];
function folhasOf(){if(!ST.folhas)ST.folhas=MULTI.cur==='alvorada'?JSON.parse(JSON.stringify(ST0.folhas)):[];return ST.folhas;}
function getFolha(id){return folhasOf().filter(function(f){return f.id===id;})[0];}
function salOf(n){var d=FUNCD[n];return d?money(d.sal):0;}
function estimar(func,vars){var s=salOf(func),h=s/220,dia=s/30,t=0;if(!s)return null;vars=normVars(vars);
 Object.keys(vars).forEach(function(k){var x=vars[k],v=vdef(k);if(!v||!vHas(k,x))return;
  if(k==='he')t+=money(x.h)*h*(1+money(x.p)/100);
  else if(k==='hen')t+=money(x.h)*h*(1+money(x.p)/100)*1.2;
  else if(k==='peric')t+=s*0.3;else if(k==='insal'){}
  else if(k==='hor')t+=money(x)*h;
  else if(k==='falta')t-=(x.m!=='horas'?money(x.d)*dia:0)+(x.m!=='dias'?money(x.h)*h:0);
  else if(k==='desc')t-=money(x.v);
  else if(k==='not')t+=money(x)*h*0.2;else if(k==='atraso')t-=money(x)*h;else if(k==='adi')t-=money(x);else t+=money(x)*(v.sg||1);});return t;}
function varsTxt(vars){var o=[];vars=normVars(vars);VARS.forEach(function(v){var x=vars[v.k];if(!vHas(v.k,x))return;
 if(v.k==='he'||v.k==='hen')o.push(v.l+' '+x.p+'%: '+x.h+' h');
 else if(v.k==='insal')o.push('Insalubridade: grau '+({'10':'mínimo (10%)','20':'médio (20%)','40':'máximo (40%)'}[x.g]||x.g));
 else if(v.k==='peric')o.push('Periculosidade: 30% sobre o salário');
 else if(v.k==='falta'){var p=[];if(x.m!=='horas'&&x.d)p.push(x.d+(money(x.d)===1?' dia':' dias'));if(x.m!=='dias'&&x.h)p.push(x.h+' h');o.push('Faltas: '+p.join(' e '));}
 else if(v.k==='desc')o.push('Desconto: R$ '+x.v+(x.d?' ('+x.d+')':''));
 else o.push(v.l+': '+(v.u==='R$'?'R$ '+x:x+' '+v.u));});return o;}
function folhaCard(f){var s=fstLbl(fst(f)),n=varsTxt(f.vars).length;return '<button type="button" class="r" data-go="folha-'+f.id+'"><span class="av2">'+esc(f.func.split(' ').map(function(x){return x[0];}).join(''))+'</span><span class="rt"><span class="a">'+esc(f.func)+'</span><span class="b">'+esc(f.tipo)+(f.retro?' · '+esc(f.comp):'')+' · '+(f.sem?'sem variáveis':n+(n===1?' variável':' variáveis'))+'</span></span><span class="pill '+s[1]+'">'+s[0]+'</span></button>';}
var FCOMP=null;
function inPer(f){return FCOMP==='all'||f.comp===FCOMP;}
