function NOW(){if(MULTI.sim){var p=MULTI.sim.split('-'),d=new Date();d.setFullYear(+p[0],+p[1]-1,+p[2]);return d;}return new Date();}
var SEXTA_SANTA={2025:'04-18',2026:'04-03',2027:'03-26',2028:'04-14'};
function feriado(d){var md=('0'+(d.getMonth()+1)).slice(-2)+'-'+('0'+d.getDate()).slice(-2);return ['01-01','04-21','05-01','09-07','10-12','11-02','11-15','11-20','12-25'].indexOf(md)>-1||SEXTA_SANTA[d.getFullYear()]===md||(((typeof MULTI!=='undefined'&&MULTI.cfg)||{}).ferMun||[]).indexOf(md)>-1;}
function diaUtil(y,m,n){var d=new Date(y,m,1),c=0;for(var i=0;i<40;i++){var w=d.getDay();if(w>0&&w<6&&!feriado(d)){c++;if(c===n)return new Date(d);}d.setDate(d.getDate()+1);}return d;}
function cParse(c){var p=(c||'').split('/');return {m:MESU.indexOf(p[0]),y:+p[1]};}
function cName(y,m){while(m<0){m+=12;y--;}while(m>11){m-=12;y++;}return MESU[m]+'/'+y;}
function cMes(c){var p=cParse(c),n=NOW();return (MESU[p.m]||'').toLowerCase()+(p.y&&p.y!==n.getFullYear()?' de '+p.y:'');}
function cap(s){s=String(s||'');return s.charAt(0).toUpperCase()+s.slice(1);}
function dOnly(d){return new Date(d.getFullYear(),d.getMonth(),d.getDate());}
function prazo(g,c){var d0=prazo0(g,c),x=+((typeof EMP==='function'&&EMP()&&EMP().pzExtra)||0);if(x){d0=new Date(d0.getFullYear(),d0.getMonth(),d0.getDate()+x);}return d0;}
function prazo0(g,c){var p=cParse(c),y=p.y,m=p.m+1;if(m>11){m=0;y++;}return g==='folha'?diaUtil(y,m,MULTI.cfg.folhaDU):new Date(y,m,Math.min(diaG(g),28));}
function compSt(g,c){var n=dOnly(NOW()),p=cParse(c);if(p.m<0)return 'futuro';if(p.y*12+p.m>n.getFullYear()*12+n.getMonth())return 'futuro';if(n>prazo(g,c)){var la=libAte(g,c);return la&&n<=la?'aberto':'encerrado';}return 'aberto';}
function abertas(g){var n=NOW();return [cName(n.getFullYear(),n.getMonth()-1),cName(n.getFullYear(),n.getMonth())].filter(function(c){return compSt(g,c)==='aberto';});}
function compPad(g){return abertas(g)[0];}
function fmtP(d){return ('0'+d.getDate()).slice(-2)+' '+MESC[d.getMonth()];}
function diasAte(d){return Math.round((dOnly(d)-dOnly(NOW()))/864e5);}
function falta(d){var n=diasAte(d);return n<0?'encerrado':n===0?'encerra hoje':n===1?'encerra amanhã':'faltam '+n+' dias';}
function urg(d){var n=diasAte(d);return n<=1?'bad':n<=5?'warn':'neutral';}
