function chatFan(cx,cy){var ico=function(g,f){var e=document.querySelector('#s-inicio [data-go="'+g+'"] .ib svg');return e?e.outerHTML:f;};
 var I=[['inicio','Início',IC.home],['dp','DP',ico('dp',IC.people)],['contabil','Gestão contábil',ico('contabil',IC.receipt)],['guias','Guias',ico('guias',IC.tax)],['config','Configurações',CH_GEAR]],rx=Math.min(148,cx-42),ry=170;
 return '<div class="chfov"></div><div class="chfttl" style="top:'+Math.round(cy+72)+'px">Menu</div>'+I.map(function(x,i){var a=(160-i*35)*Math.PI/180;return '<button type="button" class="chfi" data-go="'+x[0]+'" style="left:'+Math.round(cx+Math.cos(a)*rx-36)+'px;top:'+Math.round(cy+Math.sin(a)*ry-36)+'px;--dx:'+Math.round(-Math.cos(a)*rx)+'px;--dy:'+Math.round(-Math.sin(a)*ry)+'px"><span>'+x[2]+'</span><span'+(x[1].length>10&&x[1].indexOf(' ')<0?' class="lg"':'')+'>'+x[1]+'</span></button>';}).join('')+
 '<button type="button" class="chfx" data-chfan aria-label="Fechar menu" style="left:'+Math.round(cx-22)+'px;top:'+Math.round(cy-22)+'px">'+IC.plus+'</button>';}
function renderChat(){ST.unread=0;chatSisLimpa();save();extraLists();var C=CHT||'ct',L=chatL(C);if(C==='ct')chatRecibo(0,MULTI.cur);
 var tab=function(k,t){return '<button type="button" class="cht cht-'+k+(C===k?' on':'')+'" role="tab" aria-selected="'+(C===k)+'" data-chtab="'+k+'"><b>'+t+'</b></button>';};
 
 var head='<div class="dhd chd chtop"><button type="button" class="bk" data-back aria-label="Voltar">'+IC.back+'</button><div class="chtabs" role="tablist">'+tab('ct',CH_CT_NOME)+'<button type="button" class="chplus" data-chfan aria-expanded="false" aria-label="Abrir menu">'+IC.plus+'</button>'+tab('sis',CH_SIS_NOME)+'</div><i class="chsp" aria-hidden="true"></i></div>',tabs='';
 var info=C==='ct'?'Aqui você fala com a contadora: prazos, documentos, impostos, folha e trabalhista. Dúvidas de como usar o app vão para o '+CH_SIS_NOME+'.':'Aqui você tira dúvidas de como usar o app, com base na Ajuda. Assunto de lei, imposto ou trabalhista vai para o contador.';
 var msgs='<div class="msgs" id="msgs"><div class="chinfo chi-'+C+'">'+info+'</div>'+L.map(function(m,i){return bubble(m,i,C);}).join('')+'</div>';
 var pend=PENDCHAT?'<div class="chroute"><p>'+esc(PENDCHAT.why)+'</p><div class="g2b"><button type="button" class="wb pri" data-chroute="'+PENDCHAT.to+'">'+esc(PENDCHAT.btn)+'</button><button type="button" class="wb" data-chkeep="1">'+esc(PENDCHAT.keep)+'</button></div></div>':'';
 var who='<div class="cwho cw-'+C+'">Falando com <b>'+(C==='ct'?'o contador':'o sistema')+'</b></div>';
 return head+tabs+msgs+pend+who+'<form class="cbar" id="cform"><div class="cin"><button type="button" class="ce" data-chemo aria-label="Emojis">'+CH_ICO_EMO+'</button><textarea id="cmsg" rows="1" placeholder="'+(C==='ct'?'Escreva para o contador':'Pergunte sobre o app')+'" autocomplete="off" enterkeyhint="enter"></textarea>'+(C==='ct'?'<button type="button" class="ca" data-go="f-enviar" aria-label="Anexar arquivo">'+IC.clip+'</button>':'')+'</div><button type="submit" class="cs" aria-label="Enviar">'+IC.send+'</button><div class="chemo" hidden></div></form>';}
function chatAdd(k,t){var L=chatL(k);if(k==='sis'){var ts=Date.now(),r=sisResponder(t);r.ts=ts;L.push({me:1,t:t,h:horaAgora(),ts:ts},r);}else L.push({me:1,t:t,h:horaAgora()});save();}
function chatFim(){window.__refresh();setTimeout(function(){var m=document.getElementById('msgs');if(m)m.scrollTop=m.scrollHeight;},60);}
function sendChat(t){t=(t||'').trim();if(!t)return;var C=CHT||'ct',to=chatRota(t);
 if(to&&to!==C){PENDCHAT={to:to,text:t,why:to==='sis'?(function(){var r0=faqBusca(t)[0];return 'Essa parece uma dúvida sobre como usar o app'+(r0&&r0.r>=0.22?': “'+FAQ[r0.i][0]+'”':'')+'. Quer ver a resposta no '+CH_SIS_NOME+'?';})():'Essa parece uma dúvida de lei, imposto ou trabalhista. Quer perguntar ao contador?',btn:to==='sis'?'Ver resposta no '+CH_SIS_NOME:'Enviar ao contador',keep:C==='ct'?'Enviar ao contador mesmo assim':'Perguntar ao '+CH_SIS_NOME+' mesmo assim'};window.__refresh();return;}
 chatAdd(C,t);PENDCHAT=null;chatFim();}
function chatRoute(to,keep){if(!PENDCHAT)return;var x=PENDCHAT.text;PENDCHAT=null;if(keep){chatAdd(CHT||'ct',x);}else{CHT=to;chatAdd(to,x);}chatFim();}
function chatFaqPick(q){var i=faqIdx(q);if(i<0)return;var L=chatL('sis'),R=faqBusca(q).filter(function(x){return x.i!==i&&x.r>=0.25;}).slice(0,4).map(function(x){return FAQ[x.i][0];});var ts=Date.now(),b=faqBot(i,R);b.ts=ts;L.push({me:1,t:q,h:horaAgora(),ts:ts});L.push(b);save();chatFim();}
function chatFaqSim(ix){var L=chatL('sis'),m=L[ix];if(!m||!m.simList)return;L.push({me:0,t:'Perguntas parecidas. Toque na que for a sua:',h:horaAgora(),ts:Date.now(),opts:m.simList.slice(),ct:1,q:m.q||''});m.sim=0;save();chatFim();}
function chatToCt(ix){var m=chatL('sis')[ix],q=m&&m.q;if(!q)return;CHT='ct';PENDCHAT=null;chatAdd('ct',q);chatFim();}

function horaAgora(){var d=new Date();return hoje()+', '+('0'+d.getHours()).slice(-2)+':'+('0'+d.getMinutes()).slice(-2);}
function scrollChat(){var d=document.getElementById('s-dyn');d.scrollTop=d.scrollHeight;}

/* ===== notificações ===== */
/* Só avisos do contador (pedidos, guias, documentos, respostas e situação dos pedidos) e os alertas dos últimos dias de prazo; o chat tem o próprio sinal no ícone.
 Alertas de prazo (envios do mês, documentos pedidos, guias e férias): do 3º dia antes até o último dia, um por dia, cada um no lugar do anterior; nos envios do mês, no dia seguinte vem o aviso de envio encerrado. Depois saem de vez (também do servidor, pelo save).
 Situação de pedido some no dia seguinte ao que foi lida. Pedido de documento lido some 24 horas depois e volta como alerta nos 3 últimos dias. */
var NT_ST=/^(Pedido concluído|Contador está analisando|Pagamento confirmado|Recálculo concluído|O contador cobrou)/;
function ntId(){return 'n'+Date.now().toString(36)+Math.random().toString(36).slice(2,6);}
function ntGet(id){return (ST.notif||[]).filter(function(n){return n.id===id;})[0];}
function ntDocDe(n){if(n.t!=='O contador pediu um documento')return null;var nm=String(n.s||'').split(' · ')[0];return docsPed().filter(function(x){return pedNome(x)===nm;})[0]||null;}
function ntFase(dd,env){if(env)return dd<0?'envio encerrado':dd===0?'último dia':dd===1?'falta 1 dia':'faltam '+dd+' dias';return dd===0?'vence hoje':dd===1?'vence amanhã':'vence em '+dd+' dias';}
function ntAlertas(){var A=[],n=NOW();
 if(pf('prazo',1)!==0){
  rotItens().forEach(function(x){if(x.kind!=='prazo'||x.st!=='aberto')return;var dd=diasAte(x.pz);if(dd<0||dd>3)return;A.push({pz:'prazo|'+x.rg+'|'+x.c,fase:ntFase(dd,1),t:x.t+': '+ntFase(dd,1),s:rotSub(x),go:x.go,c:x.c});});
  ['folha','extratos','notas','despesas'].forEach(function(g){if(g==='folha'&&!FUNC.length)return;[-2,-1,0].forEach(function(k){var c=cName(n.getFullYear(),n.getMonth()+k),pz=prazo(g,c);if(diasAte(pz)!==-1||rotFeito(g,c))return;
   A.push({pz:'prazo|'+g+'|'+c,fase:'envio encerrado',t:'Envio de '+ROTG[g][3]+' de '+cMes(c)+' encerrado',s:'O prazo terminou em '+fmtP(pz)+'. O que você lançou foi ao contador automaticamente.',go:'rotinas'});});});}
 if(pf('docs',1)!==0)docsPed().forEach(function(x){if(pedFeito(x))return;var pz=pedLim(x),dd=diasAte(pz);if(dd<0||dd>3)return;A.push({pz:'docs|'+x.id,doc:x.id,fase:ntFase(dd),t:pedNome(x)+': '+ntFase(dd),s:'Pedido do contador · envie até '+fmtP(pz),go:x.go||'f-solicitado'});});
 if(pf('venc',1)!==0)GU.forEach(function(g,i){if(ST.pagas[i])return;var pz=guiaDt(g),dd=diasAte(pz),nm=g.n.split(' · ')[0];if(dd<0||dd>3)return;A.push({pz:'guia|'+nm+'|'+g.c,fase:ntFase(dd),t:'Guia '+nm+' de '+g.c+': '+ntFase(dd),s:'R$ '+g.v+' · pague até '+fmtP(pz),go:'guia-'+i});});
 ferAlertas().forEach(function(x){if(x.dd==null||x.dd<0||x.dd>3)return;A.push({pz:'fer|'+x.nm,fase:ntFase(x.dd),t:'Férias de '+x.nm+': '+ntFase(x.dd).replace('vence','vencem'),s:'Peça as férias ou adie para o próximo período aquisitivo',go:'f-ferias',pre:{func:x.nm}});});
 return A;}
/* guarda os alertas do dia como notificações e apaga o que venceu pelas regras acima; devolve 1 quando mudou algo */
function ntSync(){var L=ST.notif=ST.notif||[],t0=NOW().getTime(),hj=+dOnly(NOW()),A=ntAlertas(),ak={},orig={},tem={},mud=0;
 A.forEach(function(a){ak[a.pz]=a;});
 var K=L.filter(function(n){if(/^#?chat/.test(n.go||''))return false;
  if(n.pz){var a=ak[n.pz];return !!a&&a.fase===n.fase;}
  if(n.lido&&NT_ST.test(n.t||'')&&hj>+dOnly(new Date(n.lido)))return false;
  if(n.lido&&n.t==='O contador pediu um documento'&&t0-n.lido>=864e5)return false;
  return true;});
 if(K.length!==L.length)mud=1;
 K.forEach(function(n){if(!n.id){n.id=ntId();mud=1;}if(!n.ch){n.ch=t0;mud=1;}if(n.pz)tem[n.pz]=1;var d=ntDocDe(n);if(d)orig[d.id]=1;});
 A.slice().reverse().forEach(function(a){if(tem[a.pz]||(a.doc&&orig[a.doc]))return;var o={id:ntId(),t:a.t,s:a.s,h:horaAgora(),go:a.go,u:1,pz:a.pz,fase:a.fase,ch:t0};if(a.c)o.c=a.c;if(a.pre)o.pre=a.pre;K.unshift(o);mud=1;});
 if(mud){ST.notif=K;save();}return mud;}
function renderNotif(){if(window.__ntOn)ntSync();var L=ST.notif||[],nu=L.filter(function(n){return n.u;}).length;
 return hdr('Notificações',nu?nu+(nu>1?' não lidas':' não lida'):'Tudo lido')+
 '<section><div class="sec"><h2>Recentes</h2>'+(nu?'<button type="button" class="lnk" data-readall>Marcar todas como lidas</button>':'')+'</div><div class="card">'+(L.map(function(n){return '<button type="button" class="r nt'+(n.u?' un':'')+'" data-nt="'+esc(n.id)+'" data-go="'+esc(n.go||'inicio')+'"'+(n.c?' data-setcomp="'+esc(n.c)+'"':'')+(n.pre?' data-pre=\''+JSON.stringify(n.pre).replace(/'/g,'&#39;')+'\'':'')+'><span class="ri">'+(n.pz?IC.clock:IC.bell)+'</span><span class="rt"><span class="a">'+esc(n.t)+'</span><span class="b">'+esc(n.s)+' · '+esc(n.h)+'</span></span>'+(n.u?'<span class="ud"></span>':IC.chev18)+'</button>';}).join('')||'<p class="empty">Nenhuma notificação. Tudo em dia.</p>')+'</div></section>';}

