function arqSt(a){return ARQ_ST[a.st]||ARQ_ST.enviado;}
function compOf(x){var n=NOW();if(!x)return cName(n.getFullYear(),n.getMonth());x=String(x);
 var m=/^(\d{4})-(\d{2})/.exec(x);if(m)return cName(+m[1],+m[2]-1);
 m=/^([A-Za-zÀ-ú]+)\/(\d{4})$/.exec(x);if(m){var i=MESU.map(function(s){return s.toLowerCase();}).indexOf(m[1].toLowerCase());if(i<0)i=MESC.indexOf(m[1].toLowerCase().slice(0,3));if(i>-1)return cName(+m[2],i);}
 m=/(\d{1,2}) ([a-z]{3})(?: (\d{4}))?/.exec(x);if(m){var j=MESC.indexOf(m[2]);if(j>-1)return cName(m[3]?+m[3]:n.getFullYear(),j);}
 return cName(n.getFullYear(),n.getMonth());}
